param([Parameter(Mandatory=$true)][string]$BackendUrl)
$ErrorActionPreference='Stop';$root=Join-Path $env:ProgramFiles 'GManager Client';$state=Join-Path $env:ProgramData 'GManager\Client';$metadata=Invoke-RestMethod ([Uri]::new([Uri]$BackendUrl,'api/v1/stations/client-package'))
if($metadata.status -ne 'RELEASED'){exit 0};$current=(Get-Content (Join-Path $root 'service\appsettings.json') -Raw|ConvertFrom-Json).Client.Version;if([version]$metadata.version -le [version]$current){exit 0}
$work=Join-Path $state 'update';Remove-Item $work -Recurse -Force -ErrorAction SilentlyContinue;New-Item $work -ItemType Directory|Out-Null;$package=Join-Path $work 'client.zip';Invoke-WebRequest ([Uri]::new([Uri]$BackendUrl,$metadata.downloadUrl)) -OutFile $package
if((Get-FileHash $package -Algorithm SHA256).Hash -ne $metadata.sha256){throw 'Client package SHA-256 mismatch'};Expand-Archive $package (Join-Path $work 'candidate');$executables=Get-ChildItem (Join-Path $work 'candidate') -Recurse -Filter *.exe;if(!$executables.Count){throw 'Client package contains no executable'}
foreach($file in $executables){$signature=Get-AuthenticodeSignature $file;if($signature.Status -ne 'Valid' -or $signature.SignerCertificate.Subject -ne $metadata.signingSubject){throw "Invalid code signature: $($file.Name)"}}
$rollback=Join-Path $state 'rollback';Remove-Item $rollback -Recurse -Force -ErrorAction SilentlyContinue;Copy-Item $root $rollback -Recurse;Stop-Service GManagerClient;try{Copy-Item (Join-Path $work 'candidate\*') $root -Recurse -Force;Start-Service GManagerClient;Start-Sleep -Seconds 15;if((Get-Service GManagerClient).Status -ne 'Running'){throw 'Updated service did not remain running'}}catch{Stop-Service GManagerClient -ErrorAction SilentlyContinue;Remove-Item $root -Recurse -Force;Copy-Item $rollback $root -Recurse;Start-Service GManagerClient;throw}
